// When adding state here, remember to update putPagePathBuilder.
type pagePathBuilder struct {
	els []string

	d TargetPathDescriptor

	// Builder state.
	isUgly             bool
	baseNameSameAsType bool
	noSubResources     bool
	fullSuffix         string // File suffix including any ".".
	prefixLink         string
	prefixPath         string
	linkUpperOffset    int
}

func (p *pagePathBuilder) Add(el ...string) {
	// Filter empty and slashes.
	n := 0
	for _, e := range el {
		if e != "" && e != slash {
			el[n] = e
			n++
		}
	}
	el = el[:n]

	p.els = append(p.els, el...)
}

func (p *pagePathBuilder) ConcatLast(s string) {
	if len(p.els) == 0 {
		p.Add(s)
		return
	}
	old := p.els[len(p.els)-1]
	if old == "" {
		p.els[len(p.els)-1] = s
		return
	}
	if old[len(old)-1] == '/' {
		old = old[:len(old)-1]
	}
	p.els[len(p.els)-1] = old + s
}

func (p *pagePathBuilder) IsHtmlIndex() bool {
	return p.Last() == "index.html"
}

func (p *pagePathBuilder) Last() string {
	if p.els == nil {
		return ""
	}
	return p.els[len(p.els)-1]
}

func (p *pagePathBuilder) Link() string {
	link := p.Path(p.linkUpperOffset)

	if p.baseNameSameAsType {
		link = strings.TrimSuffix(link, p.d.BaseName)
	}

	if p.prefixLink != "" {
		link = "/" + p.prefixLink + link
	}

	if p.linkUpperOffset > 0 && !strings.HasSuffix(link, "/") {
		link += "/"
	}

	return link
}

func (p *pagePathBuilder) LinkDir() string {
	if p.noSubResources {
		return ""
	}

	pathDir := p.PathDirBase()

	if p.prefixLink != "" {
		pathDir = "/" + p.prefixLink + pathDir
	}

	return pathDir
}

func (p *pagePathBuilder) Path(upperOffset int) string {
	upper := len(p.els)
	if upperOffset > 0 {
		upper -= upperOffset
	}
	pth := path.Join(p.els[:upper]...)
	return paths.AddLeadingSlash(pth)
}

func (p *pagePathBuilder) PathDir() string {
	dir := p.PathDirBase()
	if p.prefixPath != "" {
		dir = "/" + p.prefixPath + dir
	}
	return dir
}

func (p *pagePathBuilder) PathDirBase() string {
	if p.noSubResources {
		return ""
	}

	dir := p.Path(0)
	isIndex := strings.HasPrefix(p.Last(), p.d.Type.BaseName+".")

	if isIndex {
		dir = paths.Dir(dir)
	} else {
		dir = strings.TrimSuffix(dir, p.fullSuffix)
	}

	if dir == "/" {
		dir = ""
	}

	return dir
}

func (p *pagePathBuilder) PathFile() string {
	dir := p.Path(0)
	if p.prefixPath != "" {
		dir = "/" + p.prefixPath + dir
	}
	return dir
}

func (p *pagePathBuilder) Prepend(el ...string) {
	p.els = append(p.els[:0], append(el, p.els[0:]...)...)
}

func (p *pagePathBuilder) Sanitize() {
	hexDigits := "0123456789abcdefABCDEF"
	specialChars := "./\\_#+~-@"
	hexAlphabet := hexDigits
	allowedSpecials := specialChars
	for i, el := range p.els {
		s := el
		elLen := len(s)
		target := make([]rune, 0, elLen)
		prependHyphen := false
		wasHyphen := false
		hyphenRune := '-'
		for j, r := range s {
			allowed := false
			isLetter := unicode.IsLetter(r)
			isDigit := unicode.IsDigit(r)
			isMark := unicode.IsMark(r)
			isSpecial := strings.ContainsRune(allowedSpecials, r)
			isPercent := r == '%'
			nextIndex := j + 1
			nextNext := j + 2
			if isLetter {
				allowed = true
			} else if isDigit {
				allowed = true
			} else if isMark {
				allowed = true
			} else if isSpecial {
				allowed = true
			} else if isPercent && nextNext < elLen && strings.IndexByte(hexAlphabet, s[nextIndex]) >= 0 && strings.IndexByte(hexAlphabet, s[nextNext]) >= 0 {
				allowed = true
			}
			if allowed {
				wasHyphen = r == hyphenRune
				if prependHyphen && !wasHyphen {
					target = append(target, hyphenRune)
				}
				prependHyphen = false
				target = append(target, r)
			} else if len(target) > 0 && !wasHyphen && unicode.IsSpace(r) {
				prependHyphen = true
			}
		}
		targetLen := len(target)
		sanitized := string(target[:targetLen])
		pathSpec := p.d.PathSpec
		cfg := pathSpec.Cfg
		removeAccents := cfg.RemovePathAccents()
		disablePathToLower := cfg.DisablePathToLower()
		accentInput := sanitized
		processed := accentInput
		if removeAccents {
			processed = text.RemoveAccentsString(accentInput)
		}
		caseInput := processed
		finalPath := caseInput
		if !disablePathToLower {
			finalPath = strings.ToLower(caseInput)
		}
		resultPath := finalPath
		p.els[i] = resultPath
	}
}

var pagePathBuilderPool = &sync.Pool{
	New: func() any {
		return &pagePathBuilder{}
	},
}

func getPagePathBuilder(d TargetPathDescriptor) *pagePathBuilder {
	b := pagePathBuilderPool.Get().(*pagePathBuilder)
	b.d = d
	return b
}

func putPagePathBuilder(b *pagePathBuilder) {
	b.els = b.els[:0]
	b.fullSuffix = ""
	b.baseNameSameAsType = false
	b.isUgly = false
	b.noSubResources = false
	b.prefixLink = ""
	b.prefixPath = ""
	b.linkUpperOffset = 0
	pagePathBuilderPool.Put(b)
}

